def comprobar_datos(apps, schema_editor):
    documento = apps.get_model('webcitt', 'DocumentoExpediente')
    duplicados = (documento.objects.using(schema_editor.connection.alias)
                  .values('unidad_id', 'exigido_id', 'anio', 'corte', 'mes')
                  .annotate(total=models.Count('pk')).filter(total__gt=1))
    if duplicados.exists():
        raise RuntimeError('Hay tramos duplicados del expediente. Revisa su historia antes de migrar; '
                           'esta migración no elimina ni fusiona documentos.')
    politica = apps.get_model('webcitt', 'PoliticaDeCalidad')
    if politica.objects.using(schema_editor.connection.alias).filter(
            models.Q(minimo_cumplimiento__gt=100)
            | models.Q(penalizacion_entrega_tardia__gt=100)).exists():
        raise RuntimeError('La política de calidad debe tener porcentajes entre 0 y 100 antes de migrar.')


def enlazar_versiones(apps, schema_editor):
    documento = apps.get_model('webcitt', 'DocumentoExpediente')
    auditoria = apps.get_model('webcitt', 'RegistroAuditoriaUnidad')
    alias = schema_editor.connection.alias
    for fila in documento.objects.using(alias).select_related('recurso').iterator():
        if fila.evaluacion is not None:
            if fila.estado == 'validado':
                fila.evaluacion_version = fila.version
            else:
                anteriores = {campo: getattr(fila, campo) for campo in (
                    'evaluacion', 'evaluacion_observacion', 'evaluacion_fortalezas',
                    'evaluacion_debilidades', 'evaluacion_recomendaciones', 'evaluado_por_id',
                    'version', 'recurso_id')}
                anteriores['evaluado_en'] = fila.evaluado_en.isoformat() if fila.evaluado_en else None
                auditoria.objects.using(alias).create(
                    unidad_id=fila.unidad_id, accion='actualizar', entidad='webcitt.DocumentoExpediente',
                    objeto_id=str(fila.pk), descripcion='Migración: conserva e invalida la evaluación de una entrega reabierta.',
                    datos_anteriores=anteriores, datos_nuevos={'evaluacion': None})
                fila.evaluacion = None
                fila.evaluado_en = fila.evaluado_por_id = None
                for campo in ('observacion', 'fortalezas', 'debilidades', 'recomendaciones'):
                    setattr(fila, f'evaluacion_{campo}', '')
        if fila.recurso_id:
            # El servicio de carga asignaba certificado únicamente después de
            # validar el PDF firmado; no se infiere la firma del estado validado.
            fila.firma_verificada = bool(fila.recurso.tipo_adjunto == 'certificado'
                                         and fila.recurso.seguridad_verificada and fila.cargado_en)
            if fila.cargado_en and (not fila.generado_en or fila.cargado_en >= fila.generado_en):
                fila.entregado_en = fila.cargado_en
            elif fila.estado == 'validado':
                fila.entregado_en = fila.validado_en or fila.recibido_en
        campos = ('firma_verificada', 'entregado_en', 'evaluacion_version', 'evaluacion',
                  'evaluacion_observacion', 'evaluacion_fortalezas', 'evaluacion_debilidades',
                  'evaluacion_recomendaciones', 'evaluado_en', 'evaluado_por_id')
        documento.objects.using(alias).filter(pk=fila.pk).update(**{
            campo: getattr(fila, campo) for campo in campos})


